(()=>{const API='https://rgluzdxikpagugpmusbp.supabase.co/rest/v1/rpc',KEY='sb_publishable_rcvNssgN4_dPnVUpjU0bjQ_1cEWsA52';let unread=0,open=false,msgs=[];const token=()=>localStorage.getItem('stolovaya:web-token')||'',point=()=>new URLSearchParams(location.search).get('point')||localStorage.getItem('stolovaya:qr-point')||'',employee=()=>localStorage.getItem('stolovaya:employee-name')||'Буфетчик';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function rpc(n,b){const r=await fetch(API+'/'+n,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json().catch(()=>null);if(!r.ok)throw new Error(d?.message||'Ошибка связи');return d}function button(){let b=document.getElementById('global-chat-entry');if(!b){b=document.createElement('button');b.id='global-chat-entry';b.style.cssText='position:fixed;right:12px;bottom:12px;z-index:10020;border:0;border-radius:999px;padding:12px 15px;background:#315f49;color:white;font-weight:800;box-shadow:0 6px 20px #0003';b.onclick=()=>show();document.body.appendChild(b)}b.textContent='💬 Чат'+(unread?' · '+unread:'')}async function refresh(mark=false){if(!token()||!point())return;try{const [m,u]=await Promise.all([rpc('public_global_chat_list',{p_token:token(),p_point_code:point(),p_limit:150}),rpc('public_global_chat_unread',{p_token:token(),p_point_code:point()})]);msgs=m;unread=Number(u?.unreadCount||0);if(mark){await rpc('public_global_chat_mark_read',{p_token:token(),p_point_code:point()});unread=0}button();if(open)draw()}catch(e){}}function draw(){let x=document.getElementById('global-chat-modal');if(!x){x=document.createElement('div');x.id='global-chat-modal';document.body.appendChild(x)}x.style.cssText='position:fixed;inset:0;z-index:10030;background:#f6f3ea;padding:14px;overflow:auto';x.innerHTML='<div style="max-width:760px;margin:auto"><div style="display:flex;align-items:center;gap:10px;position:sticky;top:0;background:#f6f3ea;padding:8px 0"><button id="chat-back" style="padding:10px">←</button><h2 style="margin:0">💬 Общий чат</h2></div><div style="display:grid;gap:9px;padding:8px 0 90px">'+(msgs.length?msgs.map(m=>'<article style="background:white;border:1px solid #ddd8cc;border-radius:14px;padding:11px"><small><b>'+esc(m.senderName)+'</b>'+(m.senderRole==='admin'?' · Администратор':m.pointName?' · '+esc(m.pointName):'')+' · '+new Date(m.createdAt).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+'</small><p style="white-space:pre-wrap;margin:6px 0 0">'+esc(m.body)+'</p></article>').join(''):'<p>Сообщений пока нет.</p>')+'</div><div style="position:fixed;left:0;right:0;bottom:0;background:#f6f3ea;padding:10px;display:flex;gap:8px"><input id="chat-input" maxlength="2000" placeholder="Сообщение всем…" style="flex:1;min-width:0;padding:12px;border-radius:12px;border:1px solid #bbb"><button id="chat-send" style="padding:10px 14px">Отправить</button></div></div>';document.getElementById('chat-back').onclick=()=>{open=false;x.remove()};document.getElementById('chat-send').onclick=send;document.getElementById('chat-input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();send()}}}async function show(){open=true;await refresh(true);draw()}async function send(){const i=document.getElementById('chat-input'),b=document.getElementById('chat-send'),body=i?.value.trim();if(!body)return;const old=b?.textContent;if(b){b.disabled=true;b.textContent='Отправляем…'}try{await rpc('public_global_chat_send',{p_token:token(),p_point_code:point(),p_body:body,p_sender_name:employee()});i.value='';await refresh(true)}catch(e){alert('Не отправилось: '+e.message)}finally{if(b){b.disabled=false;b.textContent=old||'Отправить'}}}button();refresh(false);setInterval(()=>refresh(open),15000)})();